![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

To prevent potential infinite recursion and stack overflow crashes when traversing payloads that may contain circular references, keep track of visited objects using a `WeakSet`.

```javascript
function collectRawTextStorageErrors(value, errors, visited = new WeakSet()) {
  if (value && typeof value === 'object') {
    if (visited.has(value)) return;
    visited.add(value);
  }

  if (Array.isArray(value)) {
    value.forEach((entry) => collectRawTextStorageErrors(entry, errors, visited));
    return;
  }

  if (!isRecord(value)) return;

  for (const [key, entry] of Object.entries(value)) {
    if (
      /^(raw_ms_text|official_ms_text|stored_ms_text|ms_text)$/u.test(key) &&
      typeof entry === 'string' &&
      entry.trim().length > 0
    ) {
      errors.push('raw_ms_text_storage_forbidden');
    }
    if (key === 'raw_ms_text_storage_allowed' && entry !== false) {
      errors.push('raw_ms_text_storage_forbidden');
    }
    collectRawTextStorageErrors(entry, errors, visited);
  }
}
